const schema = {
    type: "object",
    required: ["method", "json", "headers"],
    properties: {
        method:  { type: "string" },
        json:    { type: "object" },
        headers: { type: "object" },
        url:     { type: "string" }
    }
};

pm.test("响应结构符合 schema", function () {
    pm.response.to.have.jsonSchema(schema);
});

