    pm.response.to.have.status(200);
});
pm.test("无 cookie 时返回空对象", function () {
    pm.expect(pm.response.json().cookies).to.eql({});
});

const body = pm.response.json();

// 存进集合变量
pm.collectionVariables.set("uid", body.uuid);

pm.test("uuid 已存入变量", function () {
    pm.expect(pm.collectionVariables.get("uid")).to.be.a("string").and.not.empty;
});

pm.test("服务器收到了这个 uuid", function () {
    pm.expect(pm.response.json().args.uid)
      .to.eql(pm.collectionVariables.get("uid"));
});

const args = pm.response.json().args;

pm.test("uuid 是合法格式", function () {
    pm.expect(args.u).to.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/);
});

pm.test("timestamp 是正整数", function () {
    pm.expect(Number(args.t)).to.be.above(0);
});

pm.test("n 在 0-1000 之间", function () {
    pm.expect(Number(args.n)).to.be.within(0, 1000);
});
